<?php
require_once __DIR__ . '/_journey_helpers.php';
try{ if($_SERVER['REQUEST_METHOD']!=='POST'){ApiResponse::send(false,[],'Method not allowed.',[],405);exit;} $db=journeys_db(); $uid=journeys_require_auth(); if($uid===null)exit; $d=journeys_input(); if(!journeys_csrf($d)){ApiResponse::forbidden('Invalid CSRF token.');exit;} $jid=(int)($d['journey_id']??0); $invitee=(int)($d['user_id']??0); $j=$jid>0?journeys_find($db,$jid):null; if(!$j){ApiResponse::notFound('Journey not found.');exit;} if(!journeys_can_manage($db,$j,$uid)){ApiResponse::forbidden('Only owner can invite.');exit;} if(!journeys_require_active($db,$invitee) || !journeys_connected($db,$uid,$invitee)){ApiResponse::validation(['user_id'=>'Invitee must be an active accepted friend or family member.']);exit;} $db->beginTransaction(); $p=$db->prepare("INSERT INTO journey_participants (journey_id,user_id,role,status,invited_by) VALUES (:j,:u,'participant','pending',:by) ON DUPLICATE KEY UPDATE status=IF(status IN ('rejected','removed'),'pending',status), invited_by=:by"); $p->execute(['j'=>$jid,'u'=>$invitee,'by'=>$uid]); $i=$db->prepare("INSERT INTO journey_invitations (journey_id,inviter_id,invitee_id,status) VALUES (:j,:by,:u,'pending') ON DUPLICATE KEY UPDATE status=IF(status IN ('rejected','removed'),'pending',status), inviter_id=:by"); $i->execute(['j'=>$jid,'by'=>$uid,'u'=>$invitee]); NotificationService::createOnce($db,$invitee,$uid,NotificationService::TYPE_JOURNEY_INVITATION,'journey',$jid,'invited you to a shared journey.'); $db->commit(); ApiResponse::success([],'Invitation sent.'); }catch(Throwable $e){if(isset($db)&&$db->inTransaction())$db->rollBack();Logger::error('Journey invite failed',['error'=>$e->getMessage()]);ApiResponse::serverError('Unable to invite user.');}
?>
